import { useState, useRef, useEffect, useMemo } from 'react';
import type { Event } from '../../types/Event';
import type { Round } from '../../types/Round';
import { categoryForAction, colorForAction, iconForAction, matchFilter, formatFrameClock, type SpanKind } from './taxonomy';

const TL = { ruler: 26, round: 30, state: 30, span: 26, lane: 46, head: 132 };

const SPAN_COLOR: Record<SpanKind, string> = {
  round: 'var(--green-500)',
  corner_swap: 'var(--purple-600)',
  excluded: 'var(--text-muted)',
};

function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
  const ref = useRef<HTMLDivElement>(null);
  const [w, setW] = useState(0);
  useEffect(() => {
    if (!ref.current) return;
    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
    ro.observe(ref.current);
    return () => ro.disconnect();
  }, []);
  return [ref, w];
}

function fmtSec(s: number): string {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${String(sec).padStart(2, '0')}`;
}

function laneFor(e: Event): 'red' | 'blue' | null {
  if (e.corner === 0) return 'red';
  if (e.corner === 1) return 'blue';
  return null;
}

interface Hover { e: Event; x: number; color: string; text: string }

interface ClipProps {
  e: Event;
  x: number;
  color: string;
  text: string;
  flash: boolean;
  selected: boolean;
  onSeek: (frame: number) => void;
  onSelect: (id: number) => void;
  onHover: (h: Hover | null) => void;
}

function Clip({ e, x, color, text, flash, selected, onSeek, onSelect, onHover }: ClipProps) {
  return (
    <button
      className="tl-clip"
      onPointerDown={ev => ev.stopPropagation()}
      onClick={ev => { ev.stopPropagation(); onSeek(e.frame); onSelect(e.id); }}
      onMouseEnter={ev => onHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color, text })}
      onMouseLeave={() => onHover(null)}
      title={selected ? `${text} · Delete to remove` : text}
      style={{
        position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 6,
        display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash || selected ? 6 : 4, padding: 0,
        transition: 'transform .1s',
        border: `1px solid color-mix(in srgb, ${color} ${flash || selected ? 90 : 55}%, transparent)`,
        background: `color-mix(in srgb, ${color} ${flash || selected ? 34 : 18}%, var(--surface-inner))`,
        boxShadow: selected ? `0 0 0 2px #fff, 0 0 0 3.5px ${color}` : flash ? `0 0 0 1.5px ${color}` : 'none',
        animation: 'feed-in .25s ease-out',
      }}
    >
      <span className="material-symbols-outlined" style={{ fontSize: 16, color }}>{iconForAction(e.action)}</span>
    </button>
  );
}

interface AnnotationTimelineProps {
  events: Event[];
  spans: Event[];
  rounds: Round[];
  duration: number;
  fps: number;
  currentFrame: number;
  onSeek: (frame: number) => void;
  onSetPlaying: (playing: boolean) => void;
  onUpdateSpan: (id: number, patch: { frame?: number; end_frame?: number }) => void;
  onDeleteSpan: (id: number) => void;
  onAddRound: () => void;
  flashId: number | null;
  selectedEventId: number | null;
  onSelectEvent: (id: number | null) => void;
  filter: string;
  redName: string;
  blueName: string;
  describe: (e: Event) => string;
}

export default function AnnotationTimeline({
  events, spans, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, onUpdateSpan, onDeleteSpan, onAddRound,
  flashId, selectedEventId, onSelectEvent, filter, redName, blueName, describe,
}: AnnotationTimelineProps) {
  const [zoom, setZoom] = useState(1);
  const [hover, setHover] = useState<Hover | null>(null);
  const [scrollRef, scrollW] = useMeasure();
  const draggingRef = useRef(false);

  const time = (currentFrame - 1) / fps;
  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
